ns=bpy.app.driver_namespace['coast_ops']
c=bpy.data.collections['Coast_HarborOffice']
root=Path(bpy.data.filepath).parent.parent
for m in list(bpy.data.materials):
    if m.name.startswith('Coast ') and m.use_nodes:
        bs=m.node_tree.nodes.get('Principled BSDF')
        tex=next((n for n in m.node_tree.nodes if n.type=='TEX_IMAGE' and n.image and 'Albedo' in n.image.name),None)
        if tex:
            m.node_tree.links.new(tex.outputs['Color'],bs.inputs['Base Color'])
for o in bpy.context.scene.objects:o.hide_set(True)
for o in c.objects:o.hide_set(False)
bpy.ops.object.select_all(action='DESELECT')
for o in c.objects:o.select_set(True)
bpy.context.view_layer.objects.active=list(c.objects)[0]
out=root/'assets'/'coast'
out.mkdir(exist_ok=True)
bpy.ops.export_scene.gltf(filepath=str(out/'harbor_office.glb'),export_format='GLB',use_selection=True,export_cameras=False,export_lights=False)
for area in bpy.context.screen.areas:
    if area.type=='VIEW_3D':
        with bpy.context.temp_override(area=area,region=next(r for r in area.regions if r.type=='WINDOW')):
            bpy.ops.view3d.view_selected(use_all_regions=False)
bpy.ops.wm.save_as_mainfile(filepath=bpy.data.filepath)
print('OFFICE_EXPORTED',out)
